window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-27e331ba3f212759"]={"versions": [{"id": "FIG-27e331ba3f212759", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>. Definiert generische Metadaten (z. B. Multiplizität, Dokumentation) für Parameterverweise.\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Einfache, typisierte 1:1-Referenz auf einen konkreten Ziel-Container.\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Polymorphe Auswahl-Referenz; erlaubt die Referenzierung alternativer Ziel-Container-Typen (1:n-Typauswahl).\n</li><li><strong><code>EcucSymbolicNameReferenceDef</code>:</strong> Spezialisierte Referenz zur Erzeugung symbolischer Handle-IDs / Defines (z. B. PDU-IDs, Dem-Event-IDs).\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Verweist auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration (z. B. System-Signals, Frames, ISignals).\n<ul class=\"fig-list\"><li><code>+ destinationType: String</code>: Qualifizierter Name/Metaklasse des Ziel-Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Verweist auf spezifische Instanzen hierarchischer Modellelemente (z. B. Port-Prototypes oder Variable-Data-Prototypes in einer SWC-Kompositionsstruktur).\n<ul class=\"fig-list\"><li><code>+ destinationContext: String</code>: Kontext-Pfad zur eindeutigen Instanzauflösung.\n</li><li><code>+ destinationType: String</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Konfigurationscontainer-Definition; spezialisiert <code>EcucContainerDef</code>.\n<ul class=\"fig-list\"><li><code>+ multipleConfigurationContainer: Boolean</code>: Flag zur Kennzeichnung, ob der Container in Multi-Configuration-Szenarien (Post-Build) instanziiert/vervielfacht werden darf.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition:</strong> <code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference</code> mit Multiplizität <code>0..*</code> (<code>*</code>) Instanzen von <code>EcucAbstractReferenceDef</code>. Ein Container kann somit beliebig viele Referenzen definieren.\n</li><li><strong>Generalisierung (Vererbung):</strong> <code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code>, <code>EcucInstanceReferenceDef</code>, <code>EcucSymbolicNameReferenceDef</code> und <code>EcucForeignReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><strong>Ziel-Assoziationen (<code>+destination</code>):</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Kardinalität <code>1</code>, annotiert mit Stereotyp <code>«atpUriDef»</code> (Identifikation des Zielcontainers über kanonische AUTOSAR-URI/Pfade).\n</li><li><code>EcucSymbolicNameReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Kardinalität <code>1</code> (feste Typbindung an genau eine Containerdefinition).\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Kardinalität <code>*</code> (Menge der zulässigen Ziel-Containertypen zur Auswahl).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-915146fb33cd1adc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>. Definiert generische Metadaten für Parameterverweise.\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Typisierte 1:1-Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Polymorphe Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucSymbolicNameReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Referenz zur Definition symbolischer Handle-IDs / Defines mit Typbindung an eine konkrete Konfigurationscontainer-Definition (<code>EcucParamConfContainerDef</code>).\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Verweist auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ destinationType :String</code>: Typname des referenzierten externen Modellelements.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext :String</code>: Kontext-Pfad zur eindeutigen Instanzauflösung.\n</li><li><code>+ destinationType :String</code>: Ziel-Metaklasse der Instanz.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Abstrakte Basisklasse aller Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildChangeable :Boolean [0..1]</code>: Kennzeichnet die Veränderbarkeit des Containers zur Post-Build-Laufzeit.\n</li><li><code>+ requiresIndex :Boolean [0..1]</code>: Gibt an, ob Instanzen des Containers indexiert werden müssen.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Standard-Container für Konfigurationsparameter.\n<ul class=\"fig-list\"><li><code>+ multipleConfigurationContainer :Boolean</code>: Bestimmt, ob der Container in Multi-Configuration-Szenarien mehrfach instanziiert werden darf.\n</li></ul>\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Auswahlliste alternativer Containerdefinitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference *</code> Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer *</code> Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice *</code> alternative Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code>, <code>EcucInstanceReferenceDef</code>, <code>EcucForeignReferenceDef</code> und <code>EcucSymbolicNameReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen (<code>+destination</code>):</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 1</code>, annotiert mit Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination *</code>, annotiert mit Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucSymbolicNameReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Rolle <code>+destination 1</code>, annotiert mit Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e5479ce737c10214", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Typisierte 1:1-Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Referenziert Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucSymbolicNameReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Symbolische Referenz mit Typbindung an eine konkrete Konfigurationscontainer-Definition (<code>EcucParamConfContainerDef</code>).\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Verweist auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ destinationType :String</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext :String</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType :String</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity :Boolean [0..1]</code>: Kennzeichnet, ob die Multiplizität des Containers post-build-variantenfähig ist.\n</li><li><code>+ requiresIndex :Boolean [0..1]</code>: Gibt an, ob für Container-Instanzen eine Indexierung gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference *</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer *</code> (<code>«atpSplitable»</code>) Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice *</code> (<code>«atpSplitable»</code>) Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 1..*</code> Elemente vom Typ <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code>, <code>EcucUriReferenceDef</code>, <code>EcucInstanceReferenceDef</code>, <code>EcucForeignReferenceDef</code> und <code>EcucSymbolicNameReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> spezialisiert <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination *</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucSymbolicNameReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucUriReferenceDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucContainerDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7bdff9d7fb7b6bcb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue :Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte 1:1-Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucSymbolicNameReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Symbolische Referenz mit Bindung an eine konkrete Konfigurationscontainer-Definition (<code>EcucParamConfContainerDef</code>).\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType :String</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext :String</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType :String</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity :Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex :Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference *</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer *</code> (<code>«atpSplitable»</code>) Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice *</code> (<code>«atpSplitable»</code>) Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 1..*</code> Elemente vom Typ <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code>, <code>EcucUriReferenceDef</code> und <code>EcucSymbolicNameReferenceDef</code> spezialisieren <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> spezialisieren <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> spezialisiert <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination *</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucSymbolicNameReferenceDef</code> → <code>EcucParamConfContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucUriReferenceDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucContainerDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5d24184243207c09", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte 1:1-Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference *</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer *</code> (<code>«atpSplitable»</code>) Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice *</code> (<code>«atpSplitable»</code>) Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 1..*</code> Elemente vom Typ <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code> und <code>EcucUriReferenceDef</code> spezialisieren <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> spezialisieren <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> spezialisiert <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination *</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucUriReferenceDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucContainerDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-9e5e861a70cd1207", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte 1:1-Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference *</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer *</code> (<code>«atpSplitable»</code>) Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice *</code> (<code>«atpSplitable»</code>) Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 1..*</code> Elemente vom Typ <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code> und <code>EcucUriReferenceDef</code> spezialisieren <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> spezialisieren <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> spezialisiert <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination *</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucUriReferenceDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucContainerDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-adb4259395420751", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts mit optionaler Kardinalität.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung mit optionaler Kardinalität.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse mit optionaler Kardinalität.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Sub-Container vom Typ <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Containerdefinitionen vom Typ <code>EcucParamConfContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Elemente vom Typ <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung (Vererbung):</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> spezialisieren <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code>, <code>EcucReferenceDef</code> und <code>EcucUriReferenceDef</code> spezialisieren <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> spezialisieren <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> spezialisiert <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> spezialisieren <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> spezialisiert <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li><li><strong>Ziel-Assoziationen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 0..1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucChoiceReferenceDef</code> → <code>EcucContainerDef</code>: Rolle <code>+destination 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucUriReferenceDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..1</code>, Stereotyp <code>«atpUriDef»</code>.\n</li><li><code>EcucContainerDef</code> → <code>EcucDestinationUriDef</code>: Rolle <code>+destinationUri 0..*</code>, Stereotyp <code>«atpUriDef»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e826c76ddee85e65", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n<ul class=\"fig-list\"><li><code>+ withAuto: Boolean [0..1]</code>: Gibt an, ob für den Wert der Referenz eine automatische Berechnung unterstützt wird.\n</li></ul>\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucChoiceContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> referenziert über <code>+destination 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code> referenziert über <code>+destination 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucUriReferenceDef</code> referenziert über <code>+destinationUri 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucDestinationUriDef</code>.\n</li><li><code>EcucContainerDef</code> referenziert über <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung:</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code> spezialisiert <code>EcucCommonAttributes</code>.\n</li><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> erben von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucReferenceDef</code>, <code>EcucChoiceReferenceDef</code> und <code>EcucUriReferenceDef</code> erben von <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> erben von <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> erbt von <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> erben von <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> erbt von <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-093a3393a8c5ccf7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n<ul class=\"fig-list\"><li><code>+ withAuto: Boolean [0..1]</code>: Gibt an, ob für den Wert der Referenz eine automatische Berechnung unterstützt wird.\n</li></ul>\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ origin: String [0..1]</code>: Spezifiziert den Ursprung bzw. die Quelle der Containerdefinition.\n</li><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucChoiceContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> referenziert über <code>+destination 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code> referenziert über <code>+destination 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucUriReferenceDef</code> referenziert über <code>+destinationUri 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucDestinationUriDef</code>.\n</li><li><code>EcucContainerDef</code> referenziert über <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung:</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code> spezialisiert <code>EcucCommonAttributes</code>.\n</li><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> erben von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucReferenceDef</code>, <code>EcucChoiceReferenceDef</code> und <code>EcucUriReferenceDef</code> erben von <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> erben von <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> erbt von <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> erben von <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> erbt von <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-04737c92b63d9474", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n<ul class=\"fig-list\"><li><code>+ withAuto: Boolean [0..1]</code>: Gibt an, ob für den Wert der Referenz eine automatische Berechnung unterstützt wird.\n</li></ul>\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ origin: String [0..1]</code>: Spezifiziert den Ursprung bzw. die Quelle der Containerdefinition.\n</li><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucChoiceContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> referenziert über <code>+destination 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code> referenziert über <code>+destination 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucUriReferenceDef</code> referenziert über <code>+destinationUri 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucDestinationUriDef</code>.\n</li><li><code>EcucContainerDef</code> referenziert über <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung:</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code> spezialisiert <code>EcucCommonAttributes</code>.\n</li><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> erben von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucReferenceDef</code>, <code>EcucChoiceReferenceDef</code> und <code>EcucUriReferenceDef</code> erben von <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> erben von <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> erbt von <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> erben von <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> erbt von <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cd93c25038cdf1ee", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n<ul class=\"fig-list\"><li><code>+ withAuto: Boolean [0..1]</code>: Gibt an, ob für den Wert der Referenz eine automatische Berechnung unterstützt wird.\n</li></ul>\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ origin: String [0..1]</code>: Spezifiziert den Ursprung bzw. die Quelle der Containerdefinition.\n</li><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucChoiceContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> referenziert über <code>+destination 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code> referenziert über <code>+destination 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucUriReferenceDef</code> referenziert über <code>+destinationUri 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucDestinationUriDef</code>.\n</li><li><code>EcucContainerDef</code> referenziert über <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung:</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code> spezialisiert <code>EcucCommonAttributes</code>.\n</li><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> erben von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucReferenceDef</code>, <code>EcucChoiceReferenceDef</code> und <code>EcucUriReferenceDef</code> erben von <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> erben von <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> erbt von <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> erben von <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> erbt von <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c7577454f01e41e6", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt auf M2-Ebene gemäß <code>AUTOSAR_TPS_ECUConfiguration</code> (Release R4.0.3).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Konfigurationsparameter-Referenzen innerhalb der ECU Configuration Parameter Definition (<code>EcucParameterDefinition</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Spezifiziert die formalen Typen von Verweisen, die ein BSW-Modul-Metamodell (<code>.bmd</code> / <code>.armd</code>) zur Designtime definieren kann, um typisierte Relationen zwischen BSW-Konfigurationscontainern untereinander sowie Verknüpfungen zu externen AUTOSAR-Modellen (z. B. System Description, FIBEX, SWC-Template) herzustellen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>EcucAbstractReferenceDef</code> (abstrakt):</strong> Basisklasse aller Referenzdefinitionen; erbt von <code>EcucCommonAttributes</code>.\n<ul class=\"fig-list\"><li><code>+ withAuto: Boolean [0..1]</code>: Gibt an, ob für den Wert der Referenz eine automatische Berechnung unterstützt wird.\n</li></ul>\n</li><li><strong><code>EcucAbstractInternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für interne Referenzen innerhalb der ECU-Konfiguration.\n<ul class=\"fig-list\"><li><code>+ requiresSymbolicNameValue: Boolean [0..1]</code>: Kennzeichnet, ob für die Referenz ein symbolischer Wert gefordert ist.\n</li></ul>\n</li><li><strong><code>EcucReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Typisierte Referenz auf eine Ziel-Containerdefinition (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucChoiceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Auswahl-Referenz auf zulässige Ziel-Containertypen (<code>EcucContainerDef</code>).\n</li><li><strong><code>EcucUriReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractInternalReferenceDef</code>. Referenz auf Ziel-URIs über <code>EcucDestinationUriDef</code>.\n</li><li><strong><code>EcucAbstractExternalReferenceDef</code> (abstrakt):</strong> Spezialisiert <code>EcucAbstractReferenceDef</code>. Basisklasse für externe Referenzen auf AUTOSAR-Modellelemente außerhalb der ECU-Konfiguration.\n</li><li><strong><code>EcucForeignReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf externe AUTOSAR-Modellelemente.\n<ul class=\"fig-list\"><li><code>+ destinationType: String [0..1]</code>: Typname des referenzierten externen Artefakts.\n</li></ul>\n</li><li><strong><code>EcucInstanceReferenceDef</code>:</strong> Spezialisiert <code>EcucAbstractExternalReferenceDef</code>. Verweist auf spezifische Instanzen im AUTOSAR-Instanzenmodell.\n<ul class=\"fig-list\"><li><code>+ destinationContext: String [0..1]</code>: Kontext-Pfad zur Instanzauflösung.\n</li><li><code>+ destinationType: String [0..1]</code>: Ziel-Metaklasse.\n</li></ul>\n</li><li><strong><code>EcucDefinitionElement</code> (abstrakt):</strong> Basisklasse für Definitionselemente.\n</li><li><strong><code>EcucContainerDef</code> (abstrakt):</strong> Spezialisiert <code>EcucDefinitionElement</code>. Basisklasse für Konfigurationscontainer.\n<ul class=\"fig-list\"><li><code>+ origin: String [0..1]</code>: Spezifiziert den Ursprung bzw. die Quelle der Containerdefinition.\n</li><li><code>+ postBuildVariantMultiplicity: Boolean [0..1]</code>: Kennzeichnet post-build-variantenfähige Multiplizität des Containers.\n</li><li><code>+ requiresIndex: Boolean [0..1]</code>: Bestimmt, ob für Container-Instanzen eine Indexierung verlangt wird.\n</li></ul>\n</li><li><strong><code>EcucParamConfContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für Parameterdefinitionen.\n</li><li><strong><code>EcucChoiceContainerDef</code>:</strong> Spezialisiert <code>EcucContainerDef</code>. Container für alternative Auswahlen.\n</li><li><strong><code>EcucDestinationUriDef</code>:</strong> Spezialisiert <code>Identifiable</code>. Definiert kanonische Ziel-URIs.\n</li><li><strong><code>EcucDestinationUriDefSet</code>:</strong> Spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Menge von Ziel-URI-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition / Aggregation:</strong>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+reference 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+subContainer 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucParamConfContainerDef</code> aggregiert über die Rolle <code>+choice 0..*</code> (<code>«atpSplitable»</code>) Instanzen von <code>EcucChoiceContainerDef</code>.\n</li><li><code>EcucDestinationUriDefSet</code> aggregiert über die Rolle <code>+destinationUriDef 0..*</code> Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Assoziationen &amp; Referenzen:</strong>\n<ul class=\"fig-list\"><li><code>EcucReferenceDef</code> referenziert über <code>+destination 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucContainerDef</code>.\n</li><li><code>EcucChoiceReferenceDef</code> referenziert über <code>+destination 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucContainerDef</code>.\n</li><li><code>EcucUriReferenceDef</code> referenziert über <code>+destinationUri 0..1</code> (<code>«atpUriDef»</code>) eine <code>EcucDestinationUriDef</code>.\n</li><li><code>EcucContainerDef</code> referenziert über <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) Instanzen von <code>EcucDestinationUriDef</code>.\n</li></ul>\n</li><li><strong>Generalisierung:</strong>\n<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code> spezialisiert <code>EcucCommonAttributes</code>.\n</li><li><code>EcucAbstractInternalReferenceDef</code> und <code>EcucAbstractExternalReferenceDef</code> erben von <code>EcucAbstractReferenceDef</code>.\n</li><li><code>EcucReferenceDef</code>, <code>EcucChoiceReferenceDef</code> und <code>EcucUriReferenceDef</code> erben von <code>EcucAbstractInternalReferenceDef</code>.\n</li><li><code>EcucInstanceReferenceDef</code> und <code>EcucForeignReferenceDef</code> erben von <code>EcucAbstractExternalReferenceDef</code>.\n</li><li><code>EcucContainerDef</code> erbt von <code>EcucDefinitionElement</code>.\n</li><li><code>EcucParamConfContainerDef</code> und <code>EcucChoiceContainerDef</code> erben von <code>EcucContainerDef</code>.\n</li><li><code>EcucDestinationUriDef</code> erbt von <code>Identifiable</code>.\n</li><li><code>EcucDestinationUriDefSet</code> spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Reine Designtime- / Generierungssemantik:</strong> Das Klassendiagramm beschreibt eine statische Metamodell-Struktur; es existieren keine Laufzeitpfade, Callbacks (Det/Dem) oder Zustandsübergänge im Target.\n</li><li><strong>Toolchain-Ablauf:</strong>\n<ol class=\"fig-list\"><li><em>Definition Phase:</em> Modulentwickler deklariert in der <code>.bmd</code>-Datei die Referenzen mit Zielen und Kardinalitäten.\n</li><li><em>Configuration Phase:</em> Integrator selektiert in der <code>.ecuc</code>-Datei die Ziel-Containerwerte.\n</li><li><em>Validation Phase:</em> Konfigurations-Tool validiert die URIs (<code>«atpUriDef»</code>), prüft <code>destinationContext</code>/<code>destinationType</code> und stellt sicher, dass referenzierte Instanzen existieren.\n</li><li><em>Generation Phase:</em> BSW-Code-Generatoren lösen die Pfade auf und generieren je nach Bindungszeit C-Datentypen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modulentwickler (BSW Module Description):</strong>\n<ul class=\"fig-list\"><li>Modulinterne und Cross-BSW-Verbindungen (z. B. <code>ComIPdu</code> → <code>PduRDestPdu</code>) erfordern <code>EcucReferenceDef</code> bzw. <code>EcucChoiceReferenceDef</code>.\n</li><li>Sollen über die Referenz konfigurierbare IDs für API-Aufrufe erzeugt werden (z. B. <code>CanIf_Transmit(CanTxPduId, ...)</code>), muss zwingend <code>EcucSymbolicNameReferenceDef</code> modelliert werden, damit der Generator symbolische Namen (<code>#define &lt;Module&gt;_&lt;Name&gt; &lt;Id&gt;</code>) im <code>_Cfg.h</code> emittiert.\n</li><li>System-Bindeglieder (z. B. Com-Signal zu System-Signal) müssen über <code>EcucForeignReferenceDef</code> bzw. <code>EcucInstanceReferenceDef</code> unter Angabe des korrekten <code>destinationType</code> (z. B. <code>&quot;ISignal&quot;</code>) und Kontexts angebunden werden.\n</li></ul>\n</li><li><strong>BSW-Stack- &amp; Code-Generator-Implementierung:</strong>\n<ul class=\"fig-list\"><li><strong>Auflösung zur Compile- / Link-Time:</strong> <code>EcucReferenceDef</code> wird typischerweise in Zeiger (z. B. <code>const PduR_DestPduConfigType* DestPduRef = &amp;PduR_DestPdu[3]</code>) oder Tabellen-Indizes transformiert.\n</li><li><strong>Post-Build-Handling (<code>multipleConfigurationContainer</code>):</strong> Verweist eine Referenz auf einen Container mit <code>multipleConfigurationContainer == TRUE</code>, darf der Generator keine flachen Direktadressen hart kodieren, sondern muss Offset- oder Indirektionsstrukturen bereitstellen, die über den aktiven Post-Build-Pointer auflösbar sind.\n</li><li><strong>Fehlerkonditionen:</strong> Eine unvollständig aufgelöste <code>EcucReferenceDef</code> (Ziel nicht gefunden oder Typ-Mismatch mit <code>destinationType</code>) muss vom Generator als fataler Validierungsfehler abgefangen werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-27e331ba3f212759", "to": "FIG-915146fb33cd1adc", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcucContainerDef:</strong> Abstrakte Metaklasse eingeführt (spezialisiert <code>EcucDefinitionElement</code>) mit den Attributen <code>postBuildChangeable :Boolean [0..1]</code> und <code>requiresIndex :Boolean [0..1]</code>.\n</li><li><strong>EcucParamConfContainerDef:</strong> Spezialisiert nun <code>EcucContainerDef</code> statt direkt <code>EcucDefinitionElement</code>.\n</li><li><strong>EcucChoiceContainerDef:</strong> Metaklasse eingeführt als Spezialisierung von <code>EcucContainerDef</code>, aggregiert <code>EcucParamConfContainerDef</code> über Kompositionsrolle <code>+choice *</code>.\n</li><li><strong>EcucParamConfContainerDef:</strong> Aggregiert Sub-Container vom Typ <code>EcucContainerDef</code> über Kompositionsrolle <code>+subContainer *</code>.\n</li><li><strong>EcucReferenceDef:</strong> Ziel-Assoziation <code>+destination 1</code> zielt nun auf <code>EcucContainerDef</code> statt auf <code>EcucParamConfContainerDef</code>.\n</li><li><strong>EcucChoiceReferenceDef:</strong> Ziel-Assoziation <code>+destination *</code> zielt nun auf <code>EcucContainerDef</code> statt auf <code>EcucParamConfContainerDef</code> und ist mit dem Stereotyp <code>«atpUriDef»</code> annotiert.\n</li><li><strong>EcucSymbolicNameReferenceDef:</strong> Ziel-Assoziation <code>+destination 1</code> auf <code>EcucParamConfContainerDef</code> ist mit dem Stereotyp <code>«atpUriDef»</code> annotiert.\n</li></ul>"}, {"from": "FIG-915146fb33cd1adc", "to": "FIG-e5479ce737c10214", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcucContainerDef:</strong> Attribut <code>postBuildChangeable :Boolean [0..1]</code> entfernt und durch <code>postBuildVariantMultiplicity :Boolean [0..1]</code> ersetzt.\n</li><li><strong>EcucParamConfContainerDef:</strong> Attribut <code>multipleConfigurationContainer :Boolean</code> entfernt.\n</li><li><strong>EcucUriReferenceDef:</strong> Metaklasse eingeführt als Spezialisierung von <code>EcucAbstractReferenceDef</code> mit Assoziation <code>+destinationUri 1</code> (<code>«atpUriDef»</code>) auf <code>EcucDestinationUriDef</code>.\n</li><li><strong>EcucDestinationUriDef:</strong> Metaklasse eingeführt (Stereotyp <code>Identifiable</code>).\n</li><li><strong>EcucDestinationUriDefSet:</strong> Metaklasse eingeführt (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>), aggregiert <code>EcucDestinationUriDef</code> über Kompositionsrolle <code>+destinationUriDef 1..*</code>.\n</li><li><strong>EcucContainerDef:</strong> Assoziation <code>+destinationUri 0..*</code> (<code>«atpUriDef»</code>) auf <code>EcucDestinationUriDef</code> ergänzt.\n</li><li><strong>«atpSplitable»:</strong> Stereotyp hinzugefügt an den Kompositionsrollen <code>+reference *</code> (<code>EcucParamConfContainerDef</code>), <code>+choice *</code> (<code>EcucChoiceContainerDef</code>) und <code>+subContainer *</code> (<code>EcucParamConfContainerDef</code>).\n</li></ul>"}, {"from": "FIG-e5479ce737c10214", "to": "FIG-7bdff9d7fb7b6bcb", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcucAbstractInternalReferenceDef:</strong> Abstrakte Metaklasse eingeführt als Spezialisierung von <code>EcucAbstractReferenceDef</code> mit Attribut <code>requiresSymbolicNameValue :Boolean [0..1]</code>.\n</li><li><strong>EcucChoiceReferenceDef, EcucReferenceDef, EcucUriReferenceDef, EcucSymbolicNameReferenceDef:</strong> Spezialisieren nun <code>EcucAbstractInternalReferenceDef</code> statt direkt <code>EcucAbstractReferenceDef</code>.\n</li><li><strong>EcucAbstractExternalReferenceDef:</strong> Abstrakte Metaklasse eingeführt als Spezialisierung von <code>EcucAbstractReferenceDef</code>.\n</li><li><strong>EcucInstanceReferenceDef, EcucForeignReferenceDef:</strong> Spezialisieren nun <code>EcucAbstractExternalReferenceDef</code> statt direkt <code>EcucAbstractReferenceDef</code>.\n</li></ul>"}, {"from": "FIG-7bdff9d7fb7b6bcb", "to": "FIG-5d24184243207c09", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcucSymbolicNameReferenceDef:</strong> Metaklasse entfernt.\n</li><li><strong>EcucParamConfContainerDef:</strong> Eingehende Assoziation <code>+destination 1</code> von <code>EcucSymbolicNameReferenceDef</code> entfernt.\n</li></ul>"}, {"from": "FIG-5d24184243207c09", "to": "FIG-9e5e861a70cd1207", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e5e861a70cd1207", "to": "FIG-adb4259395420751", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>EcucInstanceReferenceDef:</strong> Attribute <code>destinationContext</code> und <code>destinationType</code> erhalten explizite Multiplizität <code>[0..1]</code>.\n</li><li><strong>EcucForeignReferenceDef:</strong> Attribut <code>destinationType</code> erhält explizite Multiplizität <code>[0..1]</code>.\n</li><li><strong>EcucReferenceDef:</strong> Assoziationsmultiplizität von <code>+destination</code> auf <code>EcucContainerDef</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><strong>EcucUriReferenceDef:</strong> Assoziationsmultiplizität von <code>+destinationUri</code> auf <code>EcucDestinationUriDef</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li><li><strong>EcucDestinationUriDefSet:</strong> Multiplizität der Aggregationsrolle <code>+destinationUriDef</code> von <code>1..*</code> auf <code>0..*</code> geändert.\n</li><li><strong>EcucParamConfContainerDef:</strong> Multiplizität der Kompositionsrollen <code>+reference</code> und <code>+subContainer</code> von <code>*</code> auf <code>0..*</code> präzisiert.\n</li><li><strong>EcucChoiceContainerDef:</strong> Multiplizität der Kompositionsrolle <code>+choice</code> von <code>*</code> auf <code>0..*</code> präzisiert.\n</li><li><strong>EcucChoiceReferenceDef:</strong> Multiplizität der Assoziationsrolle <code>+destination</code> von <code>*</code> auf <code>0..*</code> präzisiert.\n</li></ul>"}, {"from": "FIG-adb4259395420751", "to": "FIG-e826c76ddee85e65", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EcucAbstractReferenceDef</code>: Attribut <code>+ withAuto: Boolean [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-e826c76ddee85e65", "to": "FIG-093a3393a8c5ccf7", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EcucContainerDef</code>: Attribut <code>+ origin: String [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-093a3393a8c5ccf7", "to": "FIG-04737c92b63d9474", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-04737c92b63d9474", "to": "FIG-cd93c25038cdf1ee", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cd93c25038cdf1ee", "to": "FIG-c7577454f01e41e6", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
